interface LandingPageProps {
  onBuyNow: (item: CartItem) => void;
}

const LandingPageHyperDiamond: React.FC<LandingPageProps> = ({ onBuyNow }) => {

    useEffect(() => {
        const originalTitle = document.title;
        const metaDescription = document.querySelector('meta[name="description"]');
        const originalDescription = metaDescription ? metaDescription.getAttribute('content') : '';

        const newTitle = "Cera Hyper Diamond con Blindaje - Nissi Car Home";
        const newDescription = "La evolución del encerado. Recubre, sella y protege la pintura de tu vehículo con tecnología hidrofóbica de alto brillo.";
        const imageUrl = "https://image.url/hyper-diamond-social.jpg"; // Placeholder para imagen de redes sociales

        document.title = newTitle;
        if (metaDescription) {
            metaDescription.setAttribute('content', newDescription);
        }

        const tagsToSet = {
            'og:title': newTitle,
            'og:description': newDescription,
            'og:image': imageUrl,
            'og:url': window.location.href,
            'twitter:card': 'summary_large_image',
        };

        const addedTags: HTMLElement[] = [];

        Object.entries(tagsToSet).forEach(([property, content]) => {
            const tag = document.createElement('meta');
            tag.setAttribute('property', property);
            tag.setAttribute('content', content);
            document.head.appendChild(tag);
            addedTags.push(tag);
        });

        return () => {
            document.title = originalTitle;
            if (metaDescription && originalDescription) {
                metaDescription.setAttribute('content', originalDescription);
            }
            addedTags.forEach(tag => document.head.removeChild(tag));
        };
    }, []);

    return (
        <div className="bg-white">
            <LandingHero onBuyNow={onBuyNow} />
            <LandingVideo />
            <LandingFeatures /> {/* Usando el nuevo componente renombrado */}
            <LandingShowcase />
            <LandingSocialProofFAQ />
             <style>{`
                @keyframes fade-out {
                    0% { opacity: 1; transform: translateY(0) translateX(-50%); }
                    80% { opacity: 1; transform: translateY(0) translateX(-50%); }
                    100% { opacity: 0; transform: translateY(-10px) translateX(-50%); }
                }
                .animate-fade-out {
                    animation: fade-out 2s ease-in-out forwards;
                }
                .scrollbar-hide::-webkit-scrollbar {
                    display: none;
                }
                .scrollbar-hide {
                    -ms-overflow-style: none;
                    scrollbar-width: none;
                }
                @keyframes water-flow {
                  0% { background-position: 0 0; }
                  100% { background-position: -200px 400px; }
                }
                .water-overlay::after {
                  content: '';
                  position: absolute;
                  inset: 0;
                  background-image: url('https://www.transparenttextures.com/patterns/washi.png');
                  background-repeat: repeat;
                  opacity: 0.1;
                  animation: water-flow 20s linear infinite;
                  pointer-events: none;
                }
            `}</style>
        </div>
    );
};

export default LandingPageHyperDiamond;

