interface ProductCardProps {
    product: Product;
    onSelect: () => void;
    onAddToCart: (product: Product) => void;
    viewMode: 'list' | 'grid';
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onSelect, onAddToCart, viewMode }) => {
  return (
    <div 
        id={`product-card-${product.id}`}
        className={`relative z-0 ${viewMode === 'grid' ? 'h-full hover:z-10' : 'w-full'}`}
    >
        <div 
            onClick={onSelect}
            className={`
                cursor-pointer transition-all duration-300 ease-out
                ${viewMode === 'list' 
                    ? 'flex flex-row items-center p-2 gap-3 bg-white/40 backdrop-blur-md border border-white/30 rounded-lg hover:shadow-lg' 
                    : 'flex flex-col h-full bg-white/20 backdrop-blur-xl border border-white/30 rounded-2xl shadow-xl hover:shadow-2xl hover:scale-110'
                }
            `}
        >
            <div className={`flex-shrink-0 ${viewMode === 'list' ? 'w-24' : 'w-full p-6'}`}>
                <div>
                    <img src={product.image} alt={product.name} className={`
                        w-full object-contain drop-shadow-lg
                        ${viewMode === 'list' ? 'h-24' : 'h-48'}`
                    } />
                </div>
            </div>

            <div className={`flex flex-col flex-grow ${viewMode === 'grid' ? 'p-5 pt-0' : ''}`}>
                <h3 className={`font-bold text-gray-800 ${viewMode === 'list' ? 'text-base' : 'text-lg mb-2 leading-tight'}`}>{product.name}</h3>
                <p className={`text-gray-600 flex-grow ${viewMode === 'list' ? 'text-sm hidden sm:block' : 'text-xs mb-3'}`}>{product.shortDesc}</p>

                <div className={`${viewMode === 'list' ? 'flex items-center gap-4' : 'mt-auto'}`}>
                    <p className={`font-bold text-amber-600 ${viewMode === 'list' ? 'text-lg' : 'text-xl mb-3'}`}>{product.price.toLocaleString('es-CO')}</p>

                    <div className={`flex gap-2 ${viewMode === 'list' ? 'flex-1' : 'w-full'}`}>
                        <button 
                            onClick={(e) => { e.stopPropagation(); onSelect(); }} 
                            className="flex-1 bg-white/50 text-gray-800 hover:bg-white/80 backdrop-blur-sm border border-white/50 font-bold rounded-lg transition-all duration-300 active:scale-95 shadow-sm hover:shadow-md text-xs py-2 px-3 sm:text-sm"
                        >
                            Detalles
                        </button>
                        <button 
                            onClick={(e) => { e.stopPropagation(); onAddToCart(product); }} 
                            className="flex-1 bg-amber-500 text-white hover:bg-amber-600 backdrop-blur-sm border border-amber-400 font-bold rounded-lg transition-all duration-300 active:scale-95 shadow-md hover:shadow-lg text-xs py-2 px-3 sm:text-sm"
                        >
                            Añadir
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

interface ProductsProps {
    onAddToCart: (product: Product) => void;
    searchTerm: string;
    activeFilters: ActiveFilters;
    onProductSelect: (product: Product) => void;
}

const Products: React.FC<ProductsProps> = ({ onAddToCart, searchTerm, activeFilters, onProductSelect }) => {
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('grid');

  const filteredProducts = useMemo(() => {
    return productsData
      .filter(product => {
        const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = activeFilters.categories.length === 0 || activeFilters.categories.includes(product.category);
        const matchesPrice = product.price >= activeFilters.priceRange.min && product.price <= activeFilters.priceRange.max;
        return matchesSearch && matchesCategory && matchesPrice;
      })
      .sort((a, b) => {
        switch (activeFilters.sortOrder) {
          case 'price-asc': return a.price - b.price;
          case 'price-desc': return b.price - a.price;
          case 'name-asc': return a.name.localeCompare(b.name);
          case 'name-desc': return b.name.localeCompare(a.name);
          default: return 0;
        }
      });
  }, [searchTerm, activeFilters]);

  return (
    <>
      <section className="py-10">
        <ProductCarousel products={productsData} onProductSelect={onProductSelect} />
      </section>

      <section id="productos" className="pb-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="p-4 sm:p-8 rounded-3xl shadow-neumorphic-outset">
            <div className="text-center mb-8 sm:mb-16">
              <h2 className="text-3xl font-extrabold text-gray-800 sm:text-4xl">
                Nuestros Productos Esenciales
              </h2>
              <p className="mt-4 max-w-2xl mx-auto text-lg text-gray-600">
                Una línea completa para el cuidado de tu vehículo y hogar, formulada con materias primas de vanguardia.
              </p>
            </div>

            <div className="flex justify-end items-center gap-2 mb-6 sm:hidden">
              <span className="text-sm font-semibold text-gray-600">Vista:</span>
              <button 
                onClick={() => setViewMode('list')} 
                className={`p-2 rounded-lg transition-colors ${viewMode === 'list' ? 'bg-amber-500/50 text-white' : 'bg-white/40'}`}
                aria-label="Vista de lista"
              >
                <ListIcon />
              </button>
              <button 
                onClick={() => setViewMode('grid')} 
                className={`p-2 rounded-lg transition-colors ${viewMode === 'grid' ? 'bg-amber-500/50 text-white' : 'bg-white/40'}`}
                aria-label="Vista de cuadrícula"
              >
                <GridIcon />
              </button>
            </div>

            <div className={`grid gap-6 sm:gap-10 ${viewMode === 'list' ? 'grid-cols-1' : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'}`}>
              {filteredProducts.map((product) => (
                <ProductCard key={product.id} product={product} onSelect={() => onProductSelect(product)} onAddToCart={onAddToCart} viewMode={viewMode} />
              ))}
            </div>
             {filteredProducts.length === 0 && (
                <div className="text-center col-span-full py-16">
                    <h3 className="text-2xl font-semibold text-gray-700">No se encontraron productos</h3>
                    <p className="text-gray-500 mt-2">Intenta ajustar tu búsqueda o filtros.</p>
                </div>
            )}
          </div>
        </div>
      </section>
    </>
  );
};

export default Products;

